{
  "type": "page",
  "title": "用户登录",
  "body": {
    "type": "form",
    "api": "/api/login",
    "body": [
      {
        "type": "input-text",
        "name": "username",
        "label": "用户名",
        "placeholder": "请输入用户名",
        "required": true
      },
      {
        "type": "input-password",
        "name": "password",
        "label": "密码",
        "placeholder": "请输入密码",
        "required": true
      },
      {
        "type": "checkbox",
        "name": "rememberMe",
        "label": "记住我",
        "value": true,
        "defaultValue": true
      }
