{
  "type": "page",
  "title": "新建订单",
  "body": {
    "type": "form",
    "api": "/api/orders",
    "body": [
      {
        "type": "input-text",
        "name": "orderNo",
        "label": "订单号",
        "required": true
      },
      {
        "type": "select",
        "name": "customerId",
        "label": "客户名",
        "source": "/api/customers?query=${q}",
        "searchable": true,
        "required": true,
        "options": []
      },
      {
        "type": "input-number",
        "name": "amount",
        "label": "金额",
        "required": true,
        "min": 0,
        "step": 0.01
      },
      {
        "type": "textarea",
        "name": "remark",
        "label": "备注",
        "placeholder": "请输入备注信息"
      }
    ],
    "actions": [
      {
        "type": "submit",
        "label": "提交"
      }
    ]
  }
}

{
  "type": "page",
  "title": "用户管理",
  "body": {
    "type": "crud",
    "api": "/api/users",
    "columns": [
      {
        "name": "id",
        "label": "ID",
        "sortable": true
      },
      {
        "name": "name",
        "label": "姓名",
        "sortable": true
      },
      {
        "name": "email",
        "label": "邮箱",
        "sortable": true
      },
      {
        "name": "role",
        "label": "角色",
        "sortable": true,
        "type": "mapping",
        "map": {
          "admin": "管理员",
          "user": "普通用户"
        }
      },
      {
        "type": "operation",
        "label": "操作",
        "buttons": [
          {
            "type": "button",
            "label": "编辑",
            "actionType": "dialog",
            "dialog": {
              "title": "编辑用户",
              "body": {
                "type": "form",
                "api": "put:/api/users/$id",
                "body": [
                  {
                    "type": "input-text",
                    "name": "name",
                    "label": "姓名",
                    "required": true
                  },
                  {
                    "type": "input-email",
                    "name": "email",
                    "label": "邮箱",
                    "required": true
                  },
                  {
                    "type": "select",
                    "name": "role",
                    "label": "角色",
                    "options": [
                      {
                        "label": "管理员",
                        "value": "admin"
                      },
                      {
                        "label": "普通用户",
                        "value": "user"
                      }
                    ],
                    "required": true
                  }
                ]
              }
            }
          },
          {
            "type": "button",
            "label": "删除",
            "actionType": "ajax",
            "confirmText": "确定要删除该用户吗？",
            "api": "delete:/api/users/$id"
          }
        ]
      }
    ],
    "filter": {
      "body": [
        {
          "type": "input-text",
          "name": "name",
          "label": "姓名"
        },
        {
          "type": "select",
          "name": "role",
          "label": "角色",
          "options": [
            {
              "label": "全部",
              "value": ""
            },
            {
              "label": "管理员",
              "value": "admin"
            },
            {
              "label": "普通用户",
              "value": "user"
            }
          ]
        }
      ],
      "submitText": "搜索",
      "resetText": "重置"
    },
    "actions": [
      {
        "type": "button",
        "label": "新增用户",
        "actionType": "dialog",
        "dialog": {
          "title": "新增用户",
          "body": {
            "type": "form",
            "api": "post:/api/users",
            "body": [
              {
                "type": "input-text",
                "name": "name",
                "label": "姓名",
                "required": true
              },
              {
                "type": "input-email",
                "name": "email",
                "label": "邮箱",
                "required": true
              },
              {
                "type": "select",
                "name": "role",
                "label": "角色",
                "options": [
                  {
                    "label": "管理员",
                    "value": "admin"
                  },
                  {
                    "label": "普通用户",
                    "value": "user"
                  }
                ],
                "required": true
              }
            ]
          }
        }
      }
    ],
    "perPage": 10,
    "perPageOptions": [10, 20, 50],
    "emptyText": "暂无数据"
  }
}

{
  "type": "page",
  "title": "用户注册",
  "body": {
    "type": "wizard",
    "steps": [
      {
        "title": "手机号验证",
        "description": "请输入手机号并获取验证码",
        "body": {
          "type": "form",
          "api": "/api/register/step1",
          "body": [
            {
              "type": "input-phone",
              "name": "phone",
              "label": "手机号",
              "required": true,
              "placeholder": "请输入您的手机号"
            },
            {
              "type": "input-code",
              "name": "code",
              "label": "验证码",
              "required": true,
              "placeholder": "请输入验证码",
              "source": "/api/sms/code?phone=${phone}"
            }
          ],
          "actions": [
            {
              "type": "submit",
              "label": "下一步",
              "level": "primary"
            }
          ]
        }
      },
      {
        "title": "设置密码",
        "description": "设置您的登录密码",
        "body": {
          "type": "form",
          "api": "/api/register/step2",
          "body": [
            {
              "type": "input-password",
              "name": "password",
              "label": "密码",
              "required": true,
              "placeholder": "请输入密码",
              "helper": "至少8位，包含大小写字母和数字"
            },
            {
              "type": "input-password",
              "name": "confirmPassword",
              "label": "确认密码",
              "required": true,
              "placeholder": "请再次输入密码"
            }
          ],
          "actions": [
            {
              "type": "button",
              "label": "上一步",
              "actionType": "prev"
            },
            {
              "type": "submit",
              "label": "下一步",
              "level": "primary"
            }
          ]
        }
      },
      {
        "title": "完善信息",
        "description": "填写您的基本信息",
        "body": {
          "type": "form",
          "api": "/api/register/step3",
          "body": [
            {
              "type": "input-text",
              "name": "username",
              "label": "用户名",
              "required": true,
              "placeholder": "请输入用户名"
            },
            {
              "type": "select",
              "name": "gender",
              "label": "性别",
              "options": [
                {"label": "男", "value": "male"},
                {"label": "女", "value": "female"},
                {"label": "保密", "value": "secret"}
              ]
            },
            {
              "type": "input-date",
              "name": "birthday",
              "label": "生日",
              "format": "YYYY-MM-DD"
            },
            {
              "type": "input-text",
              "name": "address",
              "label": "地址",
              "placeholder": "请输入您的详细地址"
            }
          ],
          "actions": [
            {
              "type": "button",
              "label": "上一步",
              "actionType": "prev"
            },
            {
              "type": "submit",
              "label": "完成注册",
              "level": "success"
            }
          ]
        }
      }
    ],
    "onEvent": {
      "submit": {
        "actions": [
          {
            "actionType": "toast",
            "args": {
              "msg": "注册成功！"
            }
          }
        ]
      }
    }
  }
}

{
