{
  "type": "page",
  "title": "管理后台首页",
  "body": {
    "type": "container",
    "className": "h-full",
    "body": [
      {
        "type": "sidebar",
        "aside": {
          "type": "nav",
          "className": "bg-gray-800 text-white h-full",
          "nav": [
            {
              "label": "首页概览",
              "to": "#/dashboard/overview",
              "icon": "home"
            },
            {
              "label": "用户管理",
              "to": "#/dashboard/users",
              "icon": "user"
            },
            {
              "label": "订单管理",
              "to": "#/dashboard/orders",
              "icon": "shopping-cart"
            },
            {
              "label": "内容管理",
              "to": "#/dashboard/content",
              "icon": "file-text"
            },
            {
              "label": "系统设置",
              "to": "#/dashboard/settings",
              "icon": "cog"
            }
          ]
        },
        "body": {
          "type": "container",
          "className": "flex-1 p-4",
          "body": [
            {
              "type": "tabs",
              "className": "mb-4",
              "tabs": [
                {
                  "title": "概览",
                  "id": "overview",
                  "body": {
                    "type": "crud",
                    "api": "/api/dashboard/overview",
                    "columns": [
                      { "name": "total_users", "label": "总用户数" },
                      { "name": "total_orders", "label": "总订单数" },
                      { "name": "revenue", "label": "今日营收" },
                      { "name": "active_users", "label": "活跃用户数" }
                    ],
                    "filter": {
                      "body": [
                        {
                          "type": "input-date",
                          "name": "date",
                          "label": "日期",
                          "value": "today"
                        }
                      ]
                    }
                  }
                },
                {
                  "title": "用户统计",
                  "id": "users",
                  "body": {
                    "type": "crud",
                    "api": "/api/dashboard/users",
                    "columns": [
                      { "name": "new_users", "label": "新增用户" },
                      { "name": "total_users", "label": "总用户" },
                      { "name": "active_ratio", "label": "活跃率" },
                      { "name": "user_growth", "label": "用户增长" }
                    ]
                  }
                },
                {
                  "title": "订单分析",
                  "id": "orders",
                  "body": {
                    "type": "crud",
                    "api": "/api/dashboard/orders",
                    "columns": [
                      { "name": "total_orders", "label": "总订单数" },
                      { "name": "completed_orders", "label": "已完成" },
                      { "name": "pending_orders", "label": "待处理" },
                      { "name": "order_value", "label": "订单总额" }
                    ]
                  }
                }
              ]
            }
          ]
        }
      }
    ]
  }
}

