{
  "type": "page",
  "title": "二维码生成器",
  "body": {
    "type": "container",
    "body": [
      {
        "type": "form",
        "title": "输入要生成二维码的文本",
        "body": [
          {
            "type": "input-text",
            "name": "text",
            "label": "文本内容",
            "placeholder": "请输入要生成二维码的文本",
            "required": true
          }
        ],
        "actions": [
          {
            "type": "submit",
            "label": "生成二维码",
            "level": "primary"
          }
        ]
      },
      {
        "type": "container",
        "className": "mt-3",
        "body": [
          {
            "type": "image",
            "name": "qrcode",
            "label": "生成的二维码",
            "imageMode": "contain",
            "style": {
              "width": "200px",
              "height": "200px",
              "border": "1px solid #ccc"
            },
            "value": "${text | qrcode}"
          }
        ]
      },
      {
        "type": "container",
        "className": "mt-3",
        "body": [
          {
            "type": "button",
            "label": "下载二维码",
            "level": "success",
            "actionType": "ajax",
            "api": "post:/api/qrcode/download",
            "confirmText": "确定要下载二维码吗？",
            "body": {
              "text": "${text}"
            },
            "onSuccess": {
              "actions": [
                {
                  "actionType": "download",
                  "url": "${data.url}",
                  "fileName": "${data.fileName}"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

