{
  "type": "page",
  "title": "用户管理",
  "body": {
    "type": "crud",
    "api": "/api/users",
    "columns": [
      {
        "name": "id",
        "label": "ID"
      },
      {
        "name": "name",
        "label": "姓名"
      },
      {
        "name": "email",
        "label": "邮箱"
      },
      {
        "name": "role",
        "label": "角色"
      },
      {
        "type": "operation",
        "label": "操作",
        "buttons": [
          {
            "type": "button",
            "label": "编辑",
            "actionType": "dialog",
            "dialog": {
              "title": "编辑用户",
              "body": {
                "type": "form",
                "api": "put:/api/users/$id",
                "body": [
                  {
                    "type": "input-text",
                    "name": "name",
                    "label": "姓名",
                    "required": true
                  },
                  {
                    "type": "input-email",
                    "name": "email",
                    "label": "邮箱"
                  },
                  {
                    "type": "select",
                    "name": "role",
                    "label": "角色",
                    "options": [
                      {
                        "label": "管理员",
                        "value": "admin"
                      },
                      {
                        "label": "普通用户",
                        "value": "user"
                      }
                    ]
                  }
                ]
              }
            }
          },
          {
            "type": "button",
            "label": "删除",
            "actionType": "ajax",
            "confirmText": "确定要删除吗？",
            "api": "delete:/api/users/$id"
          },
          {
            "type": "button",
            "label": "查看详情",
            "actionType": "dialog",
            "dialog": {
              "title": "用户详情",
              "body": {
                "type": "tpl",
                "tpl": "<div><p><strong>ID:</strong> ${id}</p><p><strong>姓名:</strong> ${name}</p><p><strong>邮箱:</strong> ${email}</p><p><strong>角色:</strong> ${role}</p></div>"
              }
            }
          }
        ]
      }
    ],
    "filter": {
      "body": [
        {
          "type": "input-text",
          "name": "name",
          "label": "姓名"
        }
      ]
    }
  }
}
